transport_function:
(async (call) => {
  const n=load("step")+1;
  const name="step_"+String(n).padStart(3,"0")+".jsonl";
  const code="with contextlib.redirect_stdout((run_dir / '"+name+"').open('w', encoding='utf-8')): print(json.dumps("+call+", separators=(',', ':'))); print(json.dumps(game.display(), separators=(',', ':')))\r\n\r\n";
  const execution=await tools.write_stdin({session_id:90140,chars:code,yield_time_ms:1000,max_output_tokens:2000});
  const r=await tools.exec_command({cmd:"Get-Content -LiteralPath '"+load("runDir")+"\\"+name+"' -Raw",max_output_tokens:24000});
  const h=load("history");h.push({step:n,code,execution:execution.output,printed:r.output});store("history",h);store("step",n);
  if(execution.output.includes("Traceback") || r.exit_code!==0) text(execution);
  text(r.output);
})
